function validate([price, special, needs]) {
  const n = price.length;
  if (n < 1 || n > 6) return 'There are 1 to 6 kinds of items.';
  if (needs.length !== n) return 'needs must have one entry per item in price.';
  if (price.some(v => !Number.isInteger(v) || v < 0 || v > 10)) return 'Each price is between 0 and 10.';
  if (needs.some(v => !Number.isInteger(v) || v < 0 || v > 10)) return 'Each need is between 0 and 10.';
  if (special.length < 1 || special.length > 100) return 'There are 1 to 100 bundles.';
  for (const offer of special) {
    if (!Array.isArray(offer) || offer.length !== n + 1) return 'Each bundle has n counts followed by its price.';
    if (offer.some(v => !Number.isInteger(v) || v < 0 || v > 50)) return 'Bundle entries are between 0 and 50.';
    if (offer.slice(0, n).every(v => v === 0)) return 'Each bundle must contain at least one item.';
  }
  return null;
}

