function shoppingOffers(price, special, needs) {
  const n = price.length;
  const memo = new Map();
  function cost(remaining) {
    const key = remaining.join(',');
    if (memo.has(key)) {
      return memo.get(key);
    }
    let best = 0;
    for (let i = 0; i < n; i++) {
      best += remaining[i] * price[i];
    }
    for (const offer of special) {
      const next = [];
      let fits = true;
      for (let i = 0; i < n; i++) {
        next.push(remaining[i] - offer[i]);
        if (next[i] < 0) {
          fits = false;
        }
      }
      if (fits) {
        best = Math.min(best, offer[n] + cost(next));
      }
    }
    memo.set(key, best);
    return best;
  }
  return cost(needs);
}

