function shoppingOffers(price, special, needs) {
  // Decide bundle by bundle how many times to buy it, then pay the rest at regular prices.
  const n = price.length;
  const go = (k, left) => {
    if (k === special.length) return left.reduce((sum, count, i) => sum + count * price[i], 0);
    let best = go(k + 1, left);
    const offer = special[k];
    if (offer.slice(0, n).every((count, i) => count <= left[i])) {
      best = Math.min(best, offer[n] + go(k, left.map((count, i) => count - offer[i])));
    }
    return best;
  };
  return go(0, needs.slice());
}

