function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const large = size === 'large';
  const n = large ? 4 + pick(3) : 1 + pick(3);
  const price = Array.from({ length: n }, () => pick(11));
  let needs;
  // Large cases keep the number of reachable needs states moderate so every case stays fast.
  do {
    needs = Array.from({ length: n }, () => pick(large ? 11 : 5));
  } while (large && needs.reduce((p, v) => p * (v + 1), 1) > 12000);
  const offers = large ? 60 + pick(41) : 1 + pick(4);
  const special = [];
  for (let k = 0; k < offers; k++) {
    const offer = Array.from({ length: n }, () => rand() < 0.5 ? 0 : 1 + pick(rand() < 0.1 ? 50 : 3));
    if (offer.every(v => v === 0)) offer[pick(n)] = 1 + pick(3);
    const regular = offer.reduce((sum, count, i) => sum + count * price[i], 0);
    offer.push(Math.min(50, Math.max(0, regular - 4 + pick(7))));
    special.push(offer);
  }
  return [price, special, needs];
}
